        getFilteredEquipment();


    /* Update number of items */

    equipmentCount.textContent =
        `${filtered.length} equipment item${
            filtered.length === 1 ? "" : "s"
        }`;


    /* No results */

    if (filtered.length === 0) {

        equipmentGrid.innerHTML = `
