}


/* =========================
   CART FUNCTIONS
   ========================= */

function addToCart(id) {

    const item =
        EQUIPMENT.find(
            equipment => equipment.id === id
        );


    /* Safety check */

    if (!item || item.available <= 0) {
        return;
    }


    /*
        Check whether the equipment
        already exists in the cart.
    */

    const existing =
        cart.find(
            cartItem => cartItem.id === id
        );


    if (existing) {

        /*
            Don't allow the user to
            exceed available quantity.
        */

        if (
            existing.quantity <
            item.available
        ) {
            existing.quantity += 1;
        }

    } else {

        /*
            Add a new equipment item
            to the cart.
        */

        cart.push({

            id: item.id,

            name: item.name,

            brand: item.brand,

            price: item.price,

            quantity: 1

        });
    }


    saveCart();

    updateCartCount();

    renderCatalog();
}


