function setupFilters() {

    filterGroups.forEach(group => {

        const heading =
            group.querySelector("h4");


        if (!heading) {
            return;
        }


        const groupName =
            heading.textContent.trim();


        group
            .querySelectorAll(
                "input[type='checkbox']"
            )
            .forEach(input => {

                input.addEventListener(
                    "change",
                    () => {

                        const label =
                            input.parentElement;


                        const labelText =
                            label
                                ? label.textContent
                                    .trim()
                                    .replace(
                                        /\s+\d+$/,
                                        ""
                                    )
                                : "";


                        /* Availability */

                        if (
                            input.id ===
                            "availableFilter"
                        ) {

                            availableOnly =
                                input.checked;
                        }


                        /* Brand */

                        else if (
                            groupName ===
                            "BRAND"
                        ) {

                            if (
                                input.checked
                            ) {

                                selectedBrands.add(
                                    labelText
                                );

                            } else {

                                selectedBrands.delete(
                                    labelText
                                );
                            }
                        }


                        /* Lab Standard */

                        else if (
                            groupName ===
                            "LAB STANDARD"
                        ) {

                            if (
                                input.checked
                            ) {

                                selectedStandards.add(
                                    labelText
                                );

                            } else {

                                selectedStandards.delete(
                                    labelText
                                );
                            }
                        }


                        renderCatalog();

                    }
                );

            });

    });
}


