/*
    Prevents HTML entered through data from
    being interpreted as actual HTML.
*/

function escapeHTML(value) {

    return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
}


/*
    Save the current cart to the browser.
*/

function saveCart() {

    localStorage.setItem(
        "mediaLabCart",
        JSON.stringify(cart)
    );
}


/*
    Update the number shown on the
    floating cart button.
*/

function updateCartCount() {

    const count = cart.reduce(
        (sum, item) => sum + item.quantity,
        0
    );

    cartCount.textContent = count;

    if (count > 0) {
        cartCount.style.display = "grid";
    } else {
        cartCount.style.display = "none";
    }
}


/*
    Check whether an equipment item
    is already inside the cart.
*/

function isInCart(id) {

    return cart.some(
        item => item.id === id
    );
}


/* =========================
   FILTERING
   ========================= */

function getFilteredEquipment() {

    return EQUIPMENT.filter(item => {

        /* Category */

        if (
            activeCategory !== "all" &&
            item.category !== activeCategory
        ) {
            return false;
        }


        /* Subcategory */

        if (
            activeSubcategory &&
            item.subcategory !== activeSubcategory
        ) {
            return false;
        }


        /* Availability */

        if (
            availableOnly &&
            item.available <= 0
        ) {
            return false;
        }


        /* Brand */

        if (
            selectedBrands.size > 0 &&
            !selectedBrands.has(item.brand)
        ) {
            return false;
        }


        /* Lab Standard */

        if (selectedStandards.size > 0) {

            const matchesStandard =
                [...selectedStandards].some(
                    standard =>
                        item.standards.includes(standard)
                );

            if (!matchesStandard) {
                return false;
            }
        }


        /* Search */

        if (searchQuery.trim() !== "") {

            const query =
                searchQuery.toLowerCase();

            const searchableText = [
                item.name,
                item.brand,
                item.category,
                item.subcategory,
                item.tag,
                item.id
            ]
                .join(" ")
                .toLowerCase();

            if (!searchableText.includes(query)) {
                return false;
            }
        }


        return true;
    });
}


