                from every category.
            */

            categoryButtons.forEach(btn => {

                btn.classList.remove("active");

            });


            /*
                Activate clicked category.
            */

            button.classList.add("active");


            /*
                Store selected category.
            */

            activeCategory =
                button.dataset.category;


            /*
                Reset subcategory when
                changing main category.
            */

            activeSubcategory = null;


            subcategoryButtons.forEach(btn => {

                btn.classList.remove("active");

            });


            renderCatalog();

        }
    );

});


/* =========================
   SUBCATEGORY TABS
   ========================= */

subcategoryButtons.forEach(button => {

    button.addEventListener(
        "click",
        () => {

            const clickedName =
                button.textContent.trim();


            /*
                Clicking the same subcategory
                again removes the filter.
            */

            if (
                activeSubcategory ===
                clickedName
            ) {

                activeSubcategory = null;

                button.classList.remove("active");

            } else {

                /*
                    Remove active state
                    from other subcategories.
                */

                subcategoryButtons.forEach(btn => {

                    btn.classList.remove("active");

                });


                button.classList.add("active");

                activeSubcategory =
                    clickedName;
            }


            renderCatalog();

        }
    );

});


/* =========================
   FILTER CHECKBOXES
   ========================= */

function setupFilters() {

    filterGroups.forEach(group => {

        const heading =
            group.querySelector("h4");


        if (!heading) {
            return;
        }


        const groupName =
            heading.textContent.trim();


        group
            .querySelectorAll(
                "input[type='checkbox']"
            )
            .forEach(input => {

                input.addEventListener(
                    "change",
                    () => {

                        const label =
                            input.parentElement;


                        const labelText =
                            label
                                ? label.textContent
                                    .trim()
                                    .replace(
                                        /\s+\d+$/,
                                        ""
                                    )
                                : "";


                        /* Availability */

                        if (
                            input.id ===
                            "availableFilter"
                        ) {

                            availableOnly =
                                input.checked;
                        }


                        /* Brand */

                        else if (
                            groupName ===
                            "BRAND"
                        ) {

                            if (
                                input.checked
                            ) {

                                selectedBrands.add(
                                    labelText
                                );

                            } else {

                                selectedBrands.delete(
                                    labelText
                                );
                            }
                        }


                        /* Lab Standard */

                        else if (
                            groupName ===
                            "LAB STANDARD"
                        ) {

                            if (
                                input.checked
                            ) {

                                selectedStandards.add(
                                    labelText
                                );

                            } else {

                                selectedStandards.delete(
                                    labelText
                                );
                            }
                        }


                        renderCatalog();

                    }
                );

            });

    });
}


/* =========================
   CLEAR ALL FILTERS
   ========================= */

clearFiltersButton.addEventListener(
    "click",
    () => {

        /* Reset filter state */

        availableOnly = false;

        selectedBrands.clear();

        selectedStandards.clear();


        /* Uncheck every checkbox */

        document
            .querySelectorAll(
                ".filter-group input[type='checkbox']"
            )
            .forEach(input => {

                input.checked = false;

            });


        /* Clear search */

        searchQuery = "";

        searchInput.value = "";


        /* Reset category */

        activeCategory = "all";

        activeSubcategory = null;


        /* Activate All Equipment */

        categoryButtons.forEach(button => {

            button.classList.toggle(
                "active",
                button.dataset.category === "all"
            );

        });


        /* Reset subcategories */

        subcategoryButtons.forEach(button => {

            button.classList.remove("active");

        });


        renderCatalog();

    }
);


/* =========================
   GRID / LIST VIEW
   ========================= */

viewButtons.forEach(
    (button, index) => {

        button.addEventListener(
            "click",
            () => {

                /*
                    Remove active state
                    from both buttons.
                */

                viewButtons.forEach(btn => {

                    btn.classList.remove("active");

                });


                button.classList.add("active");


                /*
                    First button = Grid
                    Second button = List
                */

                if (index === 0) {

                    equipmentGrid.classList.remove(
                        "list-view"
                    );

                } else {

                    equipmentGrid.classList.add(
                        "list-view"
                    );

                }

            }
        );

    }
);


